import os, shutil, subprocess, tempfile, random, sys
random.seed(12345)
PROG_CBL='/app/src/program.cbl'; PROG_PY='/app/program.py'
# precompile cobol once
build=tempfile.mkdtemp(prefix='cbuild_')
os.makedirs(build+'/src')
shutil.copy(PROG_CBL,build+'/src/program.cbl')
p=subprocess.run(['cobc','-x','-o','program','src/program.cbl'],cwd=build,capture_output=True)
assert p.returncode==0,p.stderr
COB=build+'/program'

def run(inp,a,b,t):
    outs=[]
    for lang in ('cob','py'):
        d=tempfile.mkdtemp(prefix='fz_')
        os.makedirs(d+'/data'); os.makedirs(d+'/src')
        if lang=='cob': shutil.copy(COB,d+'/program')
        else: shutil.copy(PROG_PY,d+'/program.py')
        open(d+'/data/ACCOUNTS.DAT','wb').write(a)
        open(d+'/data/BOOKS.DAT','wb').write(b)
        open(d+'/data/TRANSACTIONS.DAT','wb').write(t)
        open(d+'/src/INPUT.DAT','wb').write(inp)
        try:
            if lang=='cob':
                pr=subprocess.run(['./program'],cwd=d,capture_output=True,timeout=5)
            else:
                pr=subprocess.run([sys.executable,'program.py'],cwd=d,capture_output=True,timeout=5)
        except subprocess.TimeoutExpired:
            pr=None
        res={}
        for n in ('ACCOUNTS','BOOKS','TRANSACTIONS'):
            try: res[n]=open(f'{d}/data/{n}.DAT','rb').read()
            except Exception as e: res[n]=repr(e).encode()
        outs.append((pr.stdout if pr else b'TIMEOUT',pr.stderr if pr else b'',res))
        shutil.rmtree(d)
    return outs

def rand_id():
    return random.choice([b'U001',b'U002',b'U003',b'U004',b'U999',b'    ',b'U00',b'AAAA',bytes(random.randrange(256) for _ in range(4))])
def rand_bookid():
    return random.choice([b'B001',b'B002',b'B003',b'B004',b'B999',b'    ',b'B00X',bytes(random.randrange(256) for _ in range(4))])
def rand_bal():
    return random.choice([b'0000001180',b'0000001800',b'0000000000',b'9999999999',b'0000000500',b'          ',
                          bytes(random.choice(b'0123456789 ABCXYZ+-') for _ in range(10))])
def rand_amt():
    if random.random()<0.5:
        return b'%010d'%random.randrange(10**10)
    return bytes(random.choice(b'0123456789 ABCXYZ+-.,') for _ in range(10))

def rand_accounts():
    recs=[]
    for _ in range(random.randrange(0,6)):
        name=bytes(random.choice(b' ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghij') for _ in range(20))
        recs.append(rand_id()+name+rand_bal())
    data=b''.join(recs)
    if data and random.random()<0.1: data=data[:random.randrange(len(data))]
    return data
def rand_books():
    recs=[]
    for _ in range(random.randrange(0,6)):
        title=bytes(random.choice(b' ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghij') for _ in range(20))
        recs.append(rand_bookid()+title+rand_id())
    data=b''.join(recs)
    if data and random.random()<0.1: data=data[:random.randrange(len(data))]
    return data
def rand_trans():
    base=open('/tmp/bak/TRANSACTIONS.DAT','rb').read()
    if random.random()<0.5: return base
    recs=[]
    for _ in range(random.randrange(0,5)):
        recs.append(rand_bookid()+b'%010d'%random.randrange(10**10)+rand_id()+rand_id())
    data=b''.join(recs)
    if data and random.random()<0.1: data=data[:random.randrange(len(data))]
    return data
def rand_input():
    r=random.random()
    if r<0.55:
        s=rand_id()+rand_id()+rand_bookid()+rand_amt()
    elif r<0.8:
        s=rand_id()+rand_id()+rand_bookid()+rand_amt()
        s=s[:random.randrange(0,len(s)+1)]
    elif r<0.9:
        s=b''.join(bytes([random.randrange(256)]) for _ in range(random.randrange(0,35)))
    else:
        s=rand_id()+rand_id()+rand_bookid()+b'%010d'%random.randrange(10**10)+b'extra stuff'
    return s

bad=0
N=int(sys.argv[1]) if len(sys.argv)>1 else 150
for i in range(N):
    inp=rand_input(); a=rand_accounts(); b=rand_books(); t=rand_trans()
    c,p=run(inp,a,b,t)
    if c[2]!=p[2]:
        bad+=1
        print('MISMATCH case',i)
        print(' inp',repr(inp)); print(' a',repr(a)); print(' b',repr(b)); print(' t',repr(t))
        print(' cobout',repr(c[0])); print(' pyout ',repr(p[0]))
        for n in ('ACCOUNTS','BOOKS','TRANSACTIONS'):
            if c[2][n]!=p[2][n]:
                print(' ',n,'cob',repr(c[2][n])); print(' ',n,'py ',repr(p[2][n]))
        if bad>=10: break
print('done bad=',bad)
